-- Eliminar la base de datos si existe (útil para reinicios limpios)
DROP DATABASE IF EXISTS football_db;

-- Crear la base de datos
CREATE DATABASE football_db;

-- Usar la base de datos recién creada
USE football_db;

-- Crear una tabla de ejemplo (por ejemplo, 'users')
CREATE TABLE `players` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fifa_version` varchar(255) NOT NULL,
  `fifa_update` varchar(255) NOT NULL,
  `player_face_url` varchar(255) NOT NULL,
  `long_name` varchar(255) NOT NULL,
  `player_positions` varchar(255) NOT NULL,
  `club_name` varchar(255) DEFAULT NULL,
  `nationality_name` varchar(255) DEFAULT NULL,
  `overall` int NOT NULL,
  `potential` int NOT NULL,
  `value_eur` int DEFAULT NULL,
  `wage_eur` int DEFAULT NULL,
  `age` int NOT NULL,
  `height_cm` int DEFAULT NULL,
  `weight_kg` int DEFAULT NULL,
  `preferred_foot` varchar(255) DEFAULT NULL,
  `weak_foot` int DEFAULT NULL,
  `skill_moves` int DEFAULT NULL,
  `international_reputation` int DEFAULT NULL,
  `work_rate` varchar(255) DEFAULT NULL,
  `body_type` varchar(255) DEFAULT NULL,
  `pace` int DEFAULT NULL,
  `shooting` int DEFAULT NULL,
  `passing` int DEFAULT NULL,
  `dribbling` int DEFAULT NULL,
  `defending` int DEFAULT NULL,
  `physic` int DEFAULT NULL,
  `attacking_crossing` int DEFAULT NULL,
  `attacking_finishing` int DEFAULT NULL,
  `attacking_heading_accuracy` int DEFAULT NULL,
  `attacking_short_passing` int DEFAULT NULL,
  `attacking_volleys` int DEFAULT NULL,
  `skill_dribbling` int DEFAULT NULL,
  `skill_curve` int DEFAULT NULL,
  `skill_fk_accuracy` int DEFAULT NULL,
  `skill_long_passing` int DEFAULT NULL,
  `skill_ball_control` int DEFAULT NULL,
  `movement_acceleration` int DEFAULT NULL,
  `movement_sprint_speed` int DEFAULT NULL,
  `movement_agility` int DEFAULT NULL,
  `movement_reactions` int DEFAULT NULL,
  `movement_balance` int DEFAULT NULL,
  `power_shot_power` int DEFAULT NULL,
  `power_jumping` int DEFAULT NULL,
  `power_stamina` int DEFAULT NULL,
  `power_strength` int DEFAULT NULL,
  `power_long_shots` int DEFAULT NULL,
  `mentality_aggression` int DEFAULT NULL,
  `mentality_interceptions` int DEFAULT NULL,
  `mentality_positioning` int DEFAULT NULL,
  `mentality_vision` int DEFAULT NULL,
  `mentality_penalties` int DEFAULT NULL,
  `mentality_composure` int DEFAULT NULL,
  `defending_marking` int DEFAULT NULL,
  `defending_standing_tackle` int DEFAULT NULL,
  `defending_sliding_tackle` int DEFAULT NULL,
  `goalkeeping_diving` int DEFAULT NULL,
  `goalkeeping_handling` int DEFAULT NULL,
  `goalkeeping_kicking` int DEFAULT NULL,
  `goalkeeping_positioning` int DEFAULT NULL,
  `goalkeeping_reflexes` int DEFAULT NULL,
  `goalkeeping_speed` int DEFAULT NULL,
  `player_traits` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=161584 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


